// Einheit 7 (B2) für alle Kurse ausser Irisch. Deutsche Texte mit englischer Übersetzung als [de, en].
import { ch, bu, ty, ma } from "./courses1.js";
import DICT from "./en_dict.js";
const m = x => Array.isArray(x) ? (DICT[x[0]] = x[1], x[0]) : x;
const T = (head, ...rows) => ({ head: head.map(m), rows: rows.map(r => r.map(m)) });
const L = (id, title, rule, structure, examples, tip, ex, more, table) => ({ id, title: m(title), rule: m(rule), structure: m(structure), examples: examples.map(e => [e[0], e.length > 2 ? m([e[1], e[2]]) : e[1]]), tip: m(tip), ex, more: m(more), table });
const C = (p, o, a, e) => ch(m(p), o.map(m), a, m(e));
const Y = (p, acc, e) => ty(m(p), acc, m(e));
const B = (p, ans, extra, e) => bu(m(p), ans, extra, m(e));
const MA = pairs => ma(m(["Ordne zu", "Match"]), pairs.map(p => [p[0], m(p[1])]));
const U = t => m(t);

export const DE7 = { title: "Unit 7 · Upper intermediate", lessons: [
  L("de27", "Konjunktiv II: würde, hätte, wäre", "For wishes, polite requests and unreal situations German uses Konjunktiv II. Most verbs use würde + infinitive. haben, sein and the modal verbs have their own forms: hätte, wäre, könnte, müsste.",
    "ich würde gehen · ich hätte · ich wäre · ich könnte · Wenn ich Zeit hätte, würde ich kommen.",
    [["Ich hätte gern einen Kaffee.", "I'd like a coffee."], ["Wenn ich reich wäre, würde ich reisen.", "If I were rich, I would travel."], ["Könnten Sie mir helfen?", "Could you help me?"]],
    "In a wenn-clause the verb goes to the end: Wenn ich Zeit hätte, ... The main clause then starts with the verb: ... würde ich kommen.",
    [ch("Wenn ich Zeit ___, würde ich kommen.", ["habe", "hätte", "hatte"], 1, "Unreal condition: hätte."),
     ch("___ Sie mir bitte helfen? (polite)", ["Können", "Könnten", "Konnten"], 1, "Polite request: Könnten Sie ...?"),
     ty("Ich ___ gern Arzt. (sein, unreal wish)", ["wäre", "waere"], "sein → wäre"),
     ma("Match", [["hätte", "would have"], ["wäre", "would be"], ["könnte", "could"], ["würde", "would"]]),
     bu("Build: If I were you, I would go.", "Wenn ich du wäre würde ich gehen", ["bin", "werde"], "Wenn ich du wäre, würde ich gehen.")],
    "Konjunktiv II forms come from the past tense, often with an umlaut: hatte → hätte, war → wäre, konnte → könnte, musste → müsste. For most other verbs, würde + infinitive is normal in speech: Ich würde das kaufen. Past unreal: hätte/wäre + participle: Wenn ich das gewusst hätte, wäre ich gekommen.",
    T(["Person", "haben", "sein", "werden", "können"], ["ich", "hätte", "wäre", "würde", "könnte"], ["du", "hättest", "wärst", "würdest", "könntest"], ["er / sie / es", "hätte", "wäre", "würde", "könnte"], ["wir", "hätten", "wären", "würden", "könnten"], ["ihr", "hättet", "wärt", "würdet", "könntet"], ["sie / Sie", "hätten", "wären", "würden", "könnten"])),
  L("de28", "The passive", "The passive focuses on the action, not on who does it. It is formed with werden + past participle. The person who does it is added with von + dative.",
    "Das Haus wird gebaut. · Das Haus wurde 1900 gebaut. · Das Haus ist gebaut worden. · Hier darf nicht geraucht werden.",
    [["Hier wird Deutsch gesprochen.", "German is spoken here."], ["Das Auto wurde repariert.", "The car was repaired."], ["Die Brücke wurde von Römern gebaut.", "The bridge was built by Romans."]],
    "In the Perfekt passive, the participle of werden is worden (not geworden): Das Paket ist geschickt worden.",
    [ch("Die Tür ___ um 8 Uhr geöffnet. (present)", ["wird", "ist", "hat"], 0, "Passive present: wird + participle."),
     ch("Das Buch ___ 1950 geschrieben. (past)", ["wird", "wurde", "würde"], 1, "Passive past: wurde."),
     ty("Das Paket ist gestern geschickt ___.", ["worden"], "Perfekt passive: worden"),
     ma("Match", [["wird gebaut", "is being built"], ["wurde gebaut", "was built"], ["ist gebaut worden", "has been built"], ["muss gebaut werden", "must be built"]]),
     bu("Build: The car is being repaired.", "Das Auto wird repariert", ["wurde", "hat"], "wird + participle")],
    "Active: Der Mechaniker repariert das Auto. Passive: Das Auto wird (vom Mechaniker) repariert. The accusative object becomes the subject. With modal verbs: Das muss gemacht werden. A dative object stays dative: Mir wurde geholfen.",
    T(["Tense", "Passive", "English"], ["Präsens", "Es wird gemacht.", "It is (being) done."], ["Präteritum", "Es wurde gemacht.", "It was done."], ["Perfekt", "Es ist gemacht worden.", "It has been done."], ["Modal", "Es muss gemacht werden.", "It must be done."])),
  L("de29", "Relative clauses", "Relative clauses describe a noun. The relative pronoun takes its gender and number from the noun, but its case from its role in the clause. The verb goes to the end.",
    "der Mann, der hier wohnt · die Frau, die ich kenne · das Kind, dem ich helfe · die Stadt, in der ich lebe",
    [["Das ist der Mann, der mir geholfen hat.", "That's the man who helped me."], ["Die Wohnung, die ich gemietet habe, ist klein.", "The flat I rented is small."], ["Das ist die Firma, bei der ich arbeite.", "That's the company I work for."]],
    "A comma always comes before and after the relative clause. Prepositions go in front of the pronoun: die Freundin, mit der ich reise.",
    [ch("Der Film, ___ ich gesehen habe, war gut.", ["der", "den", "dem"], 1, "sehen + accusative, masculine → den."),
     ch("Die Kollegin, ___ ich helfe, ist neu.", ["die", "der", "denen"], 1, "helfen + dative, feminine → der."),
     ty("Das Haus, in ___ ich wohne, ist alt.", ["dem"], "in + dative (wo?), neuter → dem"),
     ma("Match", [["der Mann, der ...", "nominative"], ["den Mann, den ...", "accusative"], ["dem Mann, dem ...", "dative"], ["die Leute, denen ...", "dative plural"]]),
     bu("Build: The woman who lives here is nice.", "Die Frau die hier wohnt ist nett", ["der", "wohnen"], "die (nominative, feminine) + verb at the end")],
    "Relative pronouns look like the definite article, except in the dative plural (denen) and the genitive (dessen, deren). For places you can also use wo: die Stadt, wo ich lebe. After alles, etwas, nichts use was: Das ist alles, was ich weiss.",
    T(["Case", "masculine", "feminine", "neuter", "plural"], ["Nominative", "der", "die", "das", "die"], ["Accusative", "den", "die", "das", "die"], ["Dative", "dem", "der", "dem", "denen"], ["Genitive", "dessen", "deren", "dessen", "deren"])),
  L("de30", "zu + infinitive and um ... zu", "Many verbs and expressions are followed by zu + infinitive at the end of the clause. um ... zu expresses a purpose (in order to). With separable verbs zu goes in the middle: anzurufen.",
    "Ich versuche, pünktlich zu sein. · Es ist schwer, Deutsch zu lernen. · Ich lerne Deutsch, um in Zürich zu arbeiten. · Vergiss nicht anzurufen!",
    [["Ich habe keine Lust, heute zu kochen.", "I don't feel like cooking today."], ["Er spart, um ein Auto zu kaufen.", "He's saving to buy a car."], ["Es ist wichtig, regelmässig zu üben.", "It's important to practise regularly."]],
    "Modal verbs never take zu: Ich muss arbeiten (not: zu arbeiten). If the subject changes, use damit: Ich erkläre es, damit du es verstehst.",
    [ch("Ich versuche, mehr Sport ___.", ["machen", "zu machen", "um machen"], 1, "versuchen + zu + infinitive"),
     ch("Sie lernt, ___ die Prüfung zu bestehen.", ["um", "dass", "für"], 0, "Purpose: um ... zu"),
     ty("Vergiss nicht, mich ___! (anrufen)", ["anzurufen"], "separable: an-zu-rufen"),
     ma("Match", [["Lust haben, ... zu", "to feel like"], ["um ... zu", "in order to"], ["vergessen, ... zu", "to forget to"], ["damit", "so that (new subject)"]]),
     bu("Build: I'm learning German to work in Zurich.", "Ich lerne Deutsch um in Zürich zu arbeiten", ["damit", "arbeite"], "um ... zu + infinitive at the end")],
    "Typical triggers: anfangen, aufhören, versuchen, vergessen, hoffen, planen, Lust haben, Zeit haben, es ist wichtig / schwer / schön. ohne ... zu means 'without -ing': Er ging, ohne Tschüss zu sagen. statt ... zu means 'instead of -ing'.",
    T(["Construction", "Example", "English"], ["Verb + zu", "Ich hoffe, dich zu sehen.", "I hope to see you."], ["um ... zu", "Ich spare, um zu reisen.", "I save in order to travel."], ["ohne ... zu", "Er ging, ohne zu zahlen.", "He left without paying."], ["statt ... zu", "Statt zu lernen, schläft er.", "Instead of studying, he sleeps."], ["separable", "anzurufen, einzukaufen", "to call, to shop"])),
] };

